#!/usr/bin/env python3
import os
import zipfile
import xml.etree.ElementTree as ET
import json
import csv
import shutil

# Load update data
with open('/root/renewal_update.json', 'r', encoding='utf-8') as f:
    update_data = json.load(f)

followups = []
with open('/root/followups.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        followups.append(row)
# Sort by sequence ascending
followups.sort(key=lambda x: int(x['sequence']))

# Namespace mapping
NS = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

# Register namespace to preserve prefix
ET.register_namespace('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')
ET.register_namespace('opf', 'http://www.idpf.org/2007/opf')

def remove_linesegarray(p_elem):
    """Remove layout cache elements from a paragraph."""
    for child in list(p_elem):
        if child.tag == '{' + NS['hp'] + '}linesegarray' or child.tag == 'hp:linesegarray':
            p_elem.remove(child)

def process_section0(filepath):
    tree = ET.parse(filepath)
    root = tree.getroot()
    modified_paras = set()

    # Walk all paragraphs
    for p in root.iter('{' + NS['hp'] + '}p'):
        p_id = p.get('id')
        # Get all runs in this paragraph
        runs = list(p.iter('{' + NS['hp'] + '}run'))
        full_text = ''.join(t.text or '' for run in runs for t in run.iter('{' + NS['hp'] + '}t'))

        # Replace customer (split across runs)
        if 'Northwind' in full_text and 'Retail' in full_text and '고객사' in full_text:
            # Clear all runs, create single merged run
            for run in list(p):
                if run.tag == '{' + NS['hp'] + '}run':
                    p.remove(run)
            new_run = ET.SubElement(p, '{' + NS['hp'] + '}run', {'charPrIDRef': '0'})
            new_t = ET.SubElement(new_run, '{' + NS['hp'] + '}t')
            new_t.text = "고객사: Asteron Commerce"
            modified_paras.add(p_id)
            continue

        # Replace owner
        if '이전담당자' in full_text:
            for run in p.iter('{' + NS['hp'] + '}run'):
                for t in run.iter('{' + NS['hp'] + '}t'):
                    if t.text and '이전담당자' in t.text:
                        t.text = t.text.replace('이전담당자', update_data['owner_name'])
            modified_paras.add(p_id)

        # Replace window dates
        if '2025-04-01 ~ 2025-04-15' in full_text:
            for run in p.iter('{' + NS['hp'] + '}run'):
                for t in run.iter('{' + NS['hp'] + '}t'):
                    if t.text and '2025-04-01 ~ 2025-04-15' in t.text:
                        t.text = t.text.replace('2025-04-01 ~ 2025-04-15',
                                                f"{update_data['window_start']} ~ {update_data['window_end']}")
            modified_paras.add(p_id)

        # Replace note
        if '기존 메모를 새 메모로 바꾸세요' in full_text:
            for run in p.iter('{' + NS['hp'] + '}run'):
                for t in run.iter('{' + NS['hp'] + '}t'):
                    if t.text and '기존 메모를 새 메모로 바꾸세요' in t.text:
                        t.text = t.text.replace('기존 메모를 새 메모로 바꾸세요.', update_data['note'])
            modified_paras.add(p_id)

    # Also handle table cells for band and escalation
    for tbl in root.iter('{' + NS['hp'] + '}tbl'):
        for tc in tbl.iter('{' + NS['hp'] + '}tc'):
            for p in tc.iter('{' + NS['hp'] + '}p'):
                p_id = p.get('id')
                runs = list(p.iter('{' + NS['hp'] + '}run'))
                full_text = ''.join(t.text or '' for run in runs for t in run.iter('{' + NS['hp'] + '}t'))

                if full_text == 'Standard-18M':
                    for t in p.iter('{' + NS['hp'] + '}t'):
                        if t.text == 'Standard-18M':
                            t.text = update_data['band']
                    modified_paras.add(p_id)

                if 'ops-old@northwind.example' in full_text:
                    for t in p.iter('{' + NS['hp'] + '}t'):
                        if t.text and 'ops-old@northwind.example' in t.text:
                            t.text = t.text.replace('ops-old@northwind.example', update_data['escalation_email'])
                    modified_paras.add(p_id)

    # Remove linesegarray from modified paragraphs
    for p in root.iter('{' + NS['hp'] + '}p'):
        if p.get('id') in modified_paras:
            remove_linesegarray(p)

    tree.write(filepath, encoding='UTF-8', xml_declaration=True)

def process_section1(filepath):
    tree = ET.parse(filepath)
    root = tree.getroot()
    modified_paras = set()

    # Collect follow-up paragraphs
    followup_paras = []
    other_paras = []

    for p in root.iter('{' + NS['hp'] + '}p'):
        p_id = p.get('id')
        runs = list(p.iter('{' + NS['hp'] + '}run'))
        full_text = ''.join(t.text or '' for run in runs for t in run.iter('{' + NS['hp'] + '}t'))

        # Identify follow-up items by pattern "N. old follow-up"
        if any(full_text.startswith(f"{i}. old follow-up") for i in range(1, 4)):
            followup_paras.append(p)
        else:
            other_paras.append((p, full_text))

    # Replace follow-up text in-place (keep same paragraph elements but update text)
    followup_paras.sort(key=lambda p: int(p.get('id')))
    for i, p in enumerate(followup_paras):
        if i < len(followups):
            new_text = f"{i+1}. {followups[i]['item']}"
            # Clear runs and replace
            for run in list(p):
                if run.tag == '{' + NS['hp'] + '}run':
                    p.remove(run)
            new_run = ET.SubElement(p, '{' + NS['hp'] + '}run', {'charPrIDRef': '0'})
            new_t = ET.SubElement(new_run, '{' + NS['hp'] + '}t')
            new_t.text = new_text
            modified_paras.add(p.get('id'))

    # Replace window dates in other paragraphs
    for p, full_text in other_paras:
        p_id = p.get('id')
        if '2025-04-01 ~ 2025-04-15' in full_text:
            for run in p.iter('{' + NS['hp'] + '}run'):
                for t in run.iter('{' + NS['hp'] + '}t'):
                    if t.text and '2025-04-01 ~ 2025-04-15' in t.text:
                        t.text = t.text.replace('2025-04-01 ~ 2025-04-15',
                                                f"{update_data['window_start']} ~ {update_data['window_end']}")
            modified_paras.add(p_id)

    # Remove linesegarray from modified paragraphs
    for p in root.iter('{' + NS['hp'] + '}p'):
        if p.get('id') in modified_paras:
            remove_linesegarray(p)

    tree.write(filepath, encoding='UTF-8', xml_declaration=True)

if __name__ == '__main__':
    process_section0('/root/hwpx_work/extracted/Contents/section0.xml')
    process_section1('/root/hwpx_work/extracted/Contents/section1.xml')

    # Repackage
    output_path = '/root/renewal_playbook_updated.hwpx'
    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        for root_dir, dirs, files in os.walk('/root/hwpx_work/extracted'):
            for file in files:
                full_path = os.path.join(root_dir, file)
                arcname = os.path.relpath(full_path, '/root/hwpx_work/extracted')
                zf.write(full_path, arcname)

    print(f"Saved updated HWPX to {output_path}")

